def transform(grid):
    """Combine the four 3-row panels, retaining the first nonzero cell by priority."""
    layers = [grid[i:i + 3] for i in range(0, 12, 3)]
    out = [[0] * 6 for _ in range(3)]
    for r in range(3):
        for c in range(6):
            for k in range(4):
                if layers[k][r][c]:
                    out[r][c] = layers[k][r][c]
                    break
    return out
